function CardPicker_v2({ cards, picked, onToggle, onAddCustom, color }) {
  const [customText, setCustomText] = useState("");
  const [addingCustom, setAddingCustom] = useState(false);
  const commitCustom = () => {
    const label = customText.trim();
    if (label && onAddCustom) {
      onAddCustom(label);
    }
    setAddingCustom(false);
    setCustomText("");
  };
  return (
    <div
      style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 16 }}
    >
      {cards.map((c) => {
        const isPicked = picked.includes(c.id);
        return (
          <div
            key={c.id}
            onClick={() => onToggle(c.id)}
            style={{
              padding: "8px 14px",
              borderRadius: 18,
              background: isPicked ? `${color}20` : "rgba(255,255,255,.03)",
              color: isPicked ? color : "var(--text2)",
              border: `1px solid ${isPicked ? color : "var(--border2)"}`,
              fontSize: 13,
              fontWeight: 500,
              cursor: "pointer",
              display: "inline-flex",
              alignItems: "center",
              gap: 6,
              transition: "all .15s",
            }}
          >
            {c.icon && <span>{c.icon}</span>}
            {c.label}
            {isPicked && (
              <span
                style={{
                  fontSize: 10,
                  background: color,
                  color: "var(--bg)",
                  borderRadius: 8,
                  padding: "1px 6px",
                  fontWeight: 700,
                  marginLeft: 2,
                }}
              >
                ✓
              </span>
            )}
          </div>
        );
      })}
      {addingCustom ? (
        <input
          autoFocus
          value={customText}
          onChange={(e) => setCustomText(e.target.value)}
          onBlur={commitCustom}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              commitCustom();
            } else if (e.key === "Escape") {
              setAddingCustom(false);
              setCustomText("");
            }
          }}
          placeholder="Type and press Enter..."
          style={{
            padding: "8px 14px",
            borderRadius: 18,
            background: "transparent",
            color: "var(--text)",
            border: `1px dashed ${color}`,
            fontSize: 13,
            fontFamily: "var(--sans)",
            outline: "none",
            minWidth: 180,
          }}
        />
      ) : (
        <div
          onClick={() => setAddingCustom(true)}
          style={{
            padding: "8px 14px",
            borderRadius: 18,
            background: "transparent",
            color: "var(--text3)",
            border: "1px dashed var(--border2)",
            fontSize: 13,
            cursor: "pointer",
          }}
        >
          + Add your own
        </div>
      )}
    </div>
  );
}
// Stage 4: shared error display + retry button used by all Summarise components.
// Uniform visual treatment across PriorityItemCard_v2, SimpleItemCard_v2, SummaryGenerator_v2
// so users get a consistent failure experience regardless of which button they hit.
function SynthesizeError({ message, onRetry, color = "#ef4444" }) {
  return (
    <div
      role="alert"
      style={{
        marginTop: 8,
        padding: "8px 12px",
        background: "rgba(239,68,68,.08)",
        border: "1px solid rgba(239,68,68,.3)",
        borderLeft: `3px solid ${color}`,
        borderRadius: 6,
        display: "flex",
        alignItems: "center",
        gap: 10,
        flexWrap: "wrap",
      }}
    >
      <span style={{ fontSize: 13 }}>⚠️</span>
      <div
        style={{
          flex: 1,
          minWidth: 140,
          fontSize: 11,
          color: "var(--text2)",
          lineHeight: 1.5,
          fontFamily: "var(--sans)",
        }}
      >
        <div
          style={{
            fontSize: 9,
            fontWeight: 700,
            letterSpacing: 1.2,
            textTransform: "uppercase",
            color: "#ef4444",
            marginBottom: 2,
          }}
        >
          Synthesis failed
        </div>
        <div>{message || "Something went wrong reaching the AI."}</div>
      </div>
      <button
        onClick={onRetry}
        style={{
          padding: "4px 10px",
          borderRadius: 12,
          background: "transparent",
          color: "var(--warm)",
          border: "1px solid var(--warm)",
          cursor: "pointer",
          fontSize: 11,
          fontWeight: 600,
          fontFamily: "var(--sans)",
        }}
      >
        ↻ Try again
      </button>
    </div>
  );
}
function PriorityItemCard_v2({
  icon,
  label,
  color,
  text,
  goal,
  promptText,
  onTextChange,
  onGoalChange,
  voiceId,
  name,
  pillar,
  horizon,
  horizonYearLabel,
}) {
  const [summarising, setSummarising] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const runSynth = async () => {
    if (!(text || "").trim()) return;
    setSummarising(true);
    setErrorMsg("");
    try {
      // Item-goal intent: minimal priorContext per Q2 clarification (just voice/name/focus).
      const synthesized = await synthesize({
        intent: "item-goal",
        voiceId: voiceId || "coach",
        name: name || "you",
        focus: {
          label,
          sourceText: text || "",
          pillar: (pillar as SynthPillar) || undefined,
          horizon: (horizon as SynthHorizon) || undefined,
          horizonYearLabel,
        },
      });
      onGoalChange(synthesized);
    } catch (e: any) {
      setErrorMsg(e?.message || "Synthesis failed.");
    }
    setSummarising(false);
  };
  return (
    <div
      style={{
        marginBottom: 14,
        padding: "16px 18px",
        background: "rgba(255,255,255,.03)",
        border: "1px solid var(--border2)",
        borderLeft: `3px solid ${color}`,
        borderRadius: 8,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          marginBottom: 10,
        }}
      >
        {icon && <span style={{ fontSize: 18 }}>{icon}</span>}
        <div
          style={{
            fontFamily: "var(--serif)",
            fontSize: 19,
            fontWeight: 500,
            color: "var(--text)",
          }}
        >
          {label}
        </div>
      </div>
      <div
        style={{
          fontSize: 14,
          color: "var(--text3)",
          fontStyle: "italic",
          marginBottom: 8,
          lineHeight: 1.5,
        }}
      >
        {promptText}
      </div>
      <textarea
        value={text || ""}
        onChange={(e) => onTextChange(e.target.value)}
        placeholder="Write freely here..."
        rows={3}
        style={{
          width: "100%",
          background: "rgba(0,0,0,.2)",
          border: "1px solid var(--border2)",
          borderRadius: 4,
          padding: "10px 12px",
          color: "var(--text)",
          fontFamily: "var(--serif)",
          fontSize: 16,
          lineHeight: 1.6,
          resize: "vertical",
          outline: "none",
        }}
      />
      <div
        style={{
          display: "flex",
          gap: 10,
          marginTop: 10,
          flexWrap: "wrap",
          alignItems: "center",
        }}
      >
        <button
          onClick={runSynth}
          disabled={!(text || "").trim() || summarising}
          style={{
            padding: "6px 14px",
            borderRadius: 14,
            background: "transparent",
            color: (text || "").trim() ? "var(--warm)" : "var(--text4)",
            border: `1px solid ${(text || "").trim() ? "var(--warm)" : "var(--border2)"}`,
            cursor: (text || "").trim() ? "pointer" : "default",
            fontSize: 12,
            fontWeight: 600,
          }}
        >
          {summarising
            ? "✨ Synthesizing..."
            : goal
              ? "↺ Regenerate goal"
              : "✨ Summarise into a goal"}
        </button>
        {goal && !errorMsg && (
          <div
            style={{
              flex: 1,
              minWidth: 200,
              padding: "6px 10px",
              borderRadius: 6,
              background: `${color}15`,
              color: "var(--text)",
              fontSize: 14,
              fontStyle: "italic",
            }}
          >
            <span
              style={{
                fontSize: 9,
                letterSpacing: 1.2,
                textTransform: "uppercase",
                color,
                fontWeight: 600,
                marginRight: 8,
              }}
            >
              GOAL
            </span>
            {goal}
          </div>
        )}
      </div>
      {errorMsg && (
        <SynthesizeError message={errorMsg} onRetry={runSynth} color={color} />
      )}
    </div>
  );
}
