// W.2: SimpleItemCard_v2 — used on 3-Year + 1-Year pages (simpler than PriorityItemCard_v2, no prompt sub-label needed)
function SimpleItemCard_v2({
  icon,
  label,
  color,
  text,
  goal,
  promptText,
  onTextChange,
  onGoalChange,
  hintText,
  hintLabel,
  voiceId,
  name,
  pillar,
  horizon,
  horizonYearLabel,
}: any) {
  const [summarising, setSummarising] = useState(false);
  const [hintOpen, setHintOpen] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");
  const summarise = async () => {
    if (!(text || "").trim()) return;
    setSummarising(true);
    setErrorMsg("");
    try {
      // Item-goal intent: minimal priorContext per Q2 clarification (just voice/name/focus).
      const synthesized = await synthesize({
        intent: "item-goal",
        voiceId: voiceId || "coach",
        name: name || "you",
        focus: {
          label,
          sourceText: text || "",
          pillar: (pillar as SynthPillar) || undefined,
          horizon: (horizon as SynthHorizon) || undefined,
          horizonYearLabel,
        },
      });
      onGoalChange(synthesized);
    } catch (e: any) {
      setErrorMsg(e?.message || "Synthesis failed.");
    }
    setSummarising(false);
  };
  return (
    <div
      style={{
        marginBottom: 10,
        padding: "12px 14px",
        background: "rgba(255,255,255,.02)",
        borderLeft: `3px solid ${color}`,
        borderRadius: 6,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 6,
          marginBottom: 6,
        }}
      >
        {icon && <span style={{ fontSize: 14 }}>{icon}</span>}
        <div
          style={{
            fontFamily: "var(--serif)",
            fontSize: 16,
            fontWeight: 500,
            color: "var(--text)",
          }}
        >
          {label}
        </div>
      </div>
      {hintText && (
        <div style={{ marginBottom: 8 }}>
          <button
            onClick={() => setHintOpen((o) => !o)}
            style={{
              background: "transparent",
              border: "none",
              cursor: "pointer",
              padding: 0,
              fontSize: 10,
              fontWeight: 600,
              letterSpacing: 1.2,
              textTransform: "uppercase",
              color: "var(--text3)",
              display: "inline-flex",
              alignItems: "center",
              gap: 4,
            }}
          >
            <span>📎</span>
            <span>
              {hintOpen ? "▴" : "▾"} {hintLabel || "From BAG"}
            </span>
          </button>
          {hintOpen && (
            <div
              style={{
                marginTop: 6,
                padding: "8px 10px",
                background: "rgba(201,168,76,.06)",
                borderLeft: "2px solid var(--warm)",
                borderRadius: 4,
                fontFamily: "var(--serif)",
                fontSize: 14,
                fontStyle: "italic",
                color: "var(--text2)",
                lineHeight: 1.55,
              }}
            >
              "{hintText}"
            </div>
          )}
        </div>
      )}
      <textarea
        value={text || ""}
        onChange={(e) => onTextChange(e.target.value)}
        placeholder={promptText}
        rows={2}
        style={{
          width: "100%",
          background: "rgba(0,0,0,.2)",
          border: "1px solid var(--border2)",
          borderRadius: 4,
          padding: "8px 10px",
          color: "var(--text)",
          fontFamily: "var(--serif)",
          fontSize: 14,
          outline: "none",
          resize: "vertical",
          lineHeight: 1.5,
        }}
      />
      <div
        style={{
          display: "flex",
          gap: 8,
          marginTop: 8,
          flexWrap: "wrap",
          alignItems: "center",
        }}
      >
        <button
          onClick={summarise}
          disabled={!(text || "").trim() || summarising}
          style={{
            padding: "5px 12px",
            borderRadius: 12,
            background: "transparent",
            color: (text || "").trim() ? color : "var(--text4)",
            border: `1px solid ${(text || "").trim() ? color : "var(--border2)"}`,
            cursor: (text || "").trim() ? "pointer" : "default",
            fontSize: 11,
            fontWeight: 600,
          }}
        >
          {summarising
            ? "✨ Synthesizing..."
            : goal
              ? "↺ Regenerate goal"
              : "✨ Summarise into a goal"}
        </button>
        {goal && !errorMsg && (
          <div
            style={{
              flex: 1,
              minWidth: 180,
              padding: "4px 10px",
              borderRadius: 6,
              background: `${color}15`,
              color: "var(--text)",
              fontSize: 14,
              fontStyle: "italic",
            }}
          >
            <span
              style={{
                fontSize: 9,
                letterSpacing: 1.2,
                textTransform: "uppercase",
                color,
                fontWeight: 600,
                marginRight: 6,
              }}
            >
              GOAL
            </span>
            {goal}
          </div>
        )}
      </div>
      {errorMsg && (
        <SynthesizeError message={errorMsg} onRetry={summarise} color={color} />
      )}
    </div>
  );
}
// W.2: PrefillNote_v2 — green-left-bar notice for 3-Year / 1-Year pre-fill explainer
