function AIChat({
  voiceId,
  onVoiceChange,
  name,
  intake,
  mapData,
  sectionLabel,
  placeholder,
}) {
  const [msgs, setMsgs] = useState([]);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef(null);
  const bottomRef = useRef(null);
  const v = VOICES[voiceId];
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [msgs]);
  const send = async () => {
    const text = inputRef.current?.value?.trim();
    if (!text || loading) return;
    inputRef.current.value = "";
    const newMsgs = [...msgs, { role: "user", content: text }];
    setMsgs(newMsgs);
    setLoading(true);
    try {
      const history = newMsgs
        .slice(-8)
        .map((m) => ({ role: m.role, content: m.content }));
      const reply = await callAI(
        voiceId,
        name,
        intake,
        mapData,
        text,
        history.slice(0, -1),
      );
      setMsgs((prev) => [
        ...prev,
        { role: "assistant", content: reply, vid: voiceId },
      ]);
    } catch {
      setMsgs((prev) => [
        ...prev,
        { role: "assistant", content: "Something went wrong.", vid: voiceId },
      ]);
    }
    setLoading(false);
  };
  const contextItems = [];
  if (
    (mapData?.purpose_layers || []).filter((l) => (l || "").trim()).length > 0
  )
    contextItems.push("purpose peeling");
  if (mapData?.purpose_final || mapData?.purpose_draft)
    contextItems.push("purpose statement");
  if ((mapData?.life_areas || []).length > 0)
    contextItems.push("life priorities");
  if (mapData?.bag_growth) contextItems.push("growth vision");
  if ((mapData?.animals || []).filter((a) => a.name).length > 0)
    contextItems.push("animals");
  if ((mapData?.values || []).filter((v) => v.name).length > 0)
    contextItems.push("values");
  if (mapData?.align_direction !== undefined)
    contextItems.push("alignment scores");
  return (
    <div
      style={{
        background: "var(--bg3)",
        border: "1px solid var(--border)",
        borderRadius: 13,
        overflow: "hidden",
      }}
    >
      <div
        style={{
          padding: "9px 13px",
          borderBottom: "1px solid var(--border)",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
          <div
            style={{
              width: 6,
              height: 6,
              borderRadius: "50%",
              background: v.color,
              animation: "pulse 2s infinite",
            }}
          />
          <span
            style={{
              fontFamily: "var(--sans)",
              fontSize: 12,
              color: v.color,
              fontWeight: 700,
            }}
          >
            {v.label}
          </span>
        </div>
        <VoiceDropdown voiceId={voiceId} onSelect={onVoiceChange} />
      </div>
      {contextItems.length > 0 && (
        <div
          style={{
            padding: "7px 13px",
            borderBottom: "1px solid var(--border)",
            background: "rgba(201,168,76,.04)",
            display: "flex",
            alignItems: "center",
            gap: 6,
            flexWrap: "wrap",
          }}
        >
          <span
            style={{
              fontFamily: "var(--sans)",
              fontSize: 10,
              color: "var(--text4)",
              letterSpacing: 1,
              textTransform: "uppercase",
              flexShrink: 0,
            }}
          >
            Katherine can see:
          </span>
          {contextItems.map((item) => (
            <span
              key={item}
              style={{
                fontFamily: "var(--sans)",
                fontSize: 10,
                color: "var(--warm)",
                background: "rgba(201,168,76,.1)",
                border: "1px solid rgba(201,168,76,.2)",
                borderRadius: 10,
                padding: "2px 8px",
              }}
            >
              {item}
            </span>
          ))}
        </div>
      )}
      {msgs.length > 0 && (
        <div style={{ maxHeight: 270, overflowY: "auto", padding: "13px" }}>
          {msgs.map((m, i) => {
            const mv = m.vid ? VOICES[m.vid] : v;
            return (
              <div
                key={i}
                style={{
                  marginBottom: 13,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: m.role === "user" ? "flex-end" : "flex-start",
                }}
              >
                {m.role === "user" ? (
                  <div
                    style={{
                      background: "var(--bg4)",
                      border: "1px solid var(--border2)",
                      borderRadius: "11px 11px 3px 11px",
                      padding: "9px 13px",
                      maxWidth: "80%",
                      fontSize: 13,
                      color: "var(--text2)",
                      lineHeight: 1.6,
                    }}
                  >
                    {m.content}
                  </div>
                ) : (
                  <div style={{ maxWidth: "90%" }}>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 5,
                        marginBottom: 5,
                      }}
                    >
                      <span style={{ color: mv.color, fontSize: 12 }}>
                        {mv.icon}
                      </span>
                      <span
                        style={{
                          fontSize: 11,
                          color: "var(--text4)",
                          fontWeight: 500,
                        }}
                      >
                        {mv.short}
                      </span>
                    </div>
                    <div
                      style={{
                        fontFamily: "var(--serif)",
                        fontSize: 17,
                        lineHeight: 1.85,
                        color: "var(--text)",
                        fontWeight: 300,
                        borderLeft: `2px solid ${mv.border}`,
                        paddingLeft: 11,
                      }}
                    >
                      {m.content}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
          {loading && (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 7,
                marginBottom: 13,
              }}
            >
              <span style={{ color: v.color, fontSize: 12 }}>{v.icon}</span>
              <div className="dot-l" style={{ color: v.color }}>
                <span />
                <span />
                <span />
              </div>
            </div>
          )}
          <div ref={bottomRef} />
        </div>
      )}
      <div
        style={{
          padding: "9px 11px",
          borderTop: msgs.length > 0 ? "1px solid var(--border)" : "none",
          display: "flex",
          gap: 8,
          alignItems: "flex-end",
        }}
      >
        <textarea
          ref={inputRef}
          rows={2}
          placeholder={
            placeholder ||
            `Ask Katherine about your ${sectionLabel || "progress"}...`
          }
          className="to-field"
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              send();
            }
          }}
          style={{
            flex: 1,
            minHeight: 52,
            fontSize: 13,
            padding: "9px 11px",
            borderRadius: 8,
          }}
        />
        <button
          onClick={send}
          disabled={loading}
          style={{
            background: loading ? "var(--bg4)" : v.color,
            border: "none",
            borderRadius: 8,
            color: loading ? "var(--text4)" : "#000",
            cursor: loading ? "not-allowed" : "pointer",
            fontSize: 18,
            padding: "11px 15px",
            transition: "all .2s",
            lineHeight: 1,
          }}
        >
          →
        </button>
      </div>
      <div
        style={{
          fontSize: 11,
          color: "var(--text3)",
          textAlign: "right",
          padding: "0 11px 7px",
        }}
      >
        Enter to send · Shift+Enter for new line
      </div>
    </div>
  );
}
