                    fontSize: 15,
                    fontFamily: "var(--sans)",
                    background: "var(--bg2)",
                    border: "1px solid var(--border)",
                    borderRadius: 8,
                    color: "var(--text)",
                    outline: "none",
                    resize: "vertical",
